-- Fee letters on request, and education-loan payments.
--
-- * fee_payment.mode gains 'loan': money paid by a bank or fee-finance company
--   for an education loan. The lender and loan number go in the reference.
-- * fee_letter_request: a parent (or student) asks the office for a fee letter,
--   for example for an education loan. Nothing is generated by itself: the
--   office checks the request, issues the letter (its content is frozen in
--   `content` with a letter number) or declines it with a note. Once issued,
--   the family downloads it from their fees page.
-- Idempotent.
begin;

alter table public.fee_payment drop constraint if exists fee_payment_mode_check;
alter table public.fee_payment add constraint fee_payment_mode_check check (mode in ('cash', 'upi', 'card', 'bank', 'cheque', 'loan'));

create table if not exists public.fee_letter_request (
  id            bigint generated always as identity primary key,
  school_id     bigint not null default public.current_school_id() references public.school(id) on delete cascade,
  student_id    bigint not null references public.student(id) on delete cascade,
  academic_year_id bigint not null references public.academic_year(id) on delete cascade,
  purpose       text not null check (purpose in ('education_loan', 'visa', 'scholarship', 'employer', 'other')),
  addressed_to  text check (addressed_to is null or char_length(addressed_to) <= 120),   -- bank or organisation
  note          text check (note is null or char_length(note) <= 500),
  requested_by  uuid default auth.uid(),
  requested_name text,
  status        text not null default 'pending' check (status in ('pending', 'issued', 'declined')),
  office_note   text check (office_note is null or char_length(office_note) <= 500),
  letter_no     text,
  content       jsonb,
  decided_by    bigint references public.staff(id) on delete set null,
  decided_at    timestamptz,
  created_at    timestamptz not null default now(),
  unique (school_id, letter_no)
);
create index if not exists idx_fee_letter_school_status on public.fee_letter_request (school_id, status, created_at desc);
create index if not exists idx_fee_letter_student on public.fee_letter_request (student_id);
-- one open request per child at a time
create unique index if not exists uq_fee_letter_pending on public.fee_letter_request (student_id) where status = 'pending';

-- The requester's name is filled in by the database.
create or replace function public.fee_letter_before_insert() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  new.requested_by := auth.uid();
  select p.full_name into new.requested_name from public.profile p where p.id = auth.uid();
  new.status := 'pending'; new.letter_no := null; new.content := null; new.decided_by := null; new.decided_at := null; new.office_note := null;
  return new;
end $$;
drop trigger if exists trg_fee_letter_before_insert on public.fee_letter_request;
create trigger trg_fee_letter_before_insert before insert on public.fee_letter_request
  for each row execute function public.fee_letter_before_insert();

-- Letter numbers run per school per year: FL-2026-0001.
create or replace function public.fee_letter_number() returns trigger
language plpgsql security definer set search_path = '' as $$
declare v_prefix text; v_last int;
begin
  if new.status = 'issued' and old.status <> 'issued' then
    v_prefix := 'FL-' || to_char(now() at time zone 'Asia/Kolkata', 'YYYY') || '-';
    perform pg_advisory_xact_lock(hashtextextended('fee_letter:' || new.school_id || ':' || v_prefix, 0));
    select coalesce(max(substr(r.letter_no, length(v_prefix) + 1)::int), 0) into v_last
      from public.fee_letter_request r where r.school_id = new.school_id and r.letter_no like v_prefix || '%';
    new.letter_no := v_prefix || lpad((v_last + 1)::text, 4, '0');
    new.decided_at := now();
  elsif new.status = 'declined' and old.status <> 'declined' then
    new.decided_at := now();
  end if;
  if old.status <> 'pending' and (new.status is distinct from old.status or new.content is distinct from old.content) then
    raise exception 'This request has already been dealt with';
  end if;
  return new;
end $$;
drop trigger if exists trg_fee_letter_number on public.fee_letter_request;
create trigger trg_fee_letter_number before update on public.fee_letter_request
  for each row execute function public.fee_letter_number();

alter table public.fee_letter_request enable row level security;
drop policy if exists fee_letter_tenant on public.fee_letter_request;
create policy fee_letter_tenant on public.fee_letter_request as restrictive for all to authenticated
  using (school_id = public.current_school_id()) with check (school_id = public.current_school_id());
drop policy if exists fee_letter_read on public.fee_letter_request;
create policy fee_letter_read on public.fee_letter_request for select to authenticated
  using ((select app.is_admin_scope()) or student_id in (select app.my_owned_students()));
drop policy if exists fee_letter_ask on public.fee_letter_request;
create policy fee_letter_ask on public.fee_letter_request for insert to authenticated
  with check (student_id in (select app.my_owned_students()));
drop policy if exists fee_letter_decide on public.fee_letter_request;
create policy fee_letter_decide on public.fee_letter_request for update to authenticated
  using ((select app.is_office())) with check ((select app.is_office()));
grant select, insert, update on public.fee_letter_request to authenticated;
grant all on public.fee_letter_request to service_role;

drop trigger if exists trg_log_change on public.fee_letter_request;
create trigger trg_log_change after insert or update or delete on public.fee_letter_request
  for each row execute function public.log_change('Fee letter');

commit;
